public void runProcess(AIBBookInventoryUpdationDataContract _dataContract)
{
    AIBBookTable book = AIBBookTable::find(_dataContract.parmBookId());

    Qty currentInventory = book.currentInventory();

    Qty newTransactionQtyNeeded = _dataContract.parmNewQty() - currentInventory;

    AIBBookInventoryTransaction inventoryTransaction;

    inventoryTransaction.InventTransId = guid2Str(newGuid());
    inventoryTransaction.Book = book.RecId;
    inventoryTransaction.Qty = newTransactionQtyNeeded;

    if(inventoryTransaction.validateWrite())
    {
        inventoryTransaction.insert();
    }
    else
    {
        throw Exception::Error;
    }
}
